import{_ as t,c as r,o,a2 as a}from"./chunks/framework.bjzS3PU6.js";const h=JSON.parse('{"title":"Journal Entries - starryeyed77","description":"","frontmatter":{},"headers":[],"relativePath":"lore/JOURNAL_ENTRIES_STARRYEYED77.md","filePath":"lore/JOURNAL_ENTRIES_STARRYEYED77.md"}'),i={name:"lore/JOURNAL_ENTRIES_STARRYEYED77.md"};function n(s,e,l,u,c,m){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="journal-entries-starryeyed77" tabindex="-1">Journal Entries - starryeyed77 <a class="header-anchor" href="#journal-entries-starryeyed77" aria-label="Permalink to &quot;Journal Entries - starryeyed77&quot;">​</a></h1><h2 id="context-analysis" tabindex="-1">Context &amp; Analysis <a class="header-anchor" href="#context-analysis" aria-label="Permalink to &quot;Context &amp; Analysis&quot;">​</a></h2><p><strong>Puzzle Origin:</strong> Episode 2</p><p><strong>Key Revelations:</strong></p><ul><li>Journal entries from October 1999 - February 2000</li><li>Starryeyed77 is a freelance web designer who doesn&#39;t respond to Harmony medication</li><li>Starts noticing everyone around her becoming uniformly &quot;calm&quot; after taking Harmony</li><li>Observes strange creatures and phenomena that others dismiss or don&#39;t see</li><li>Gets recruited for cognitive testing by Miter-affiliated researchers</li><li>Has recurring dreams of a geometric symbol (likely G*BOY&#39;s sigil)</li><li>Her friend &quot;conspiracy coffee shop guy&quot; disappears after discussing Saint Juniper</li><li>She&#39;s one of the few people Harmony doesn&#39;t work on - possibly &quot;naturally gifted&quot; (Snake cohort material)</li></ul><p><strong>Timeline Highlights:</strong></p><ul><li>October 16, 1999: Meets &quot;conspiracy coffee shop guy&quot; who warns about Saint Juniper and Miter</li><li>November 3, 1999: News reports &quot;incident&quot; at Saint Juniper Research Campus</li><li>January 24, 2000: Sees a strange creature; most people walk past it normally</li><li>January 27, 2000: Doctor prescribes Harmony for anxiety</li><li>February 3, 2000: Dream of geometric cross symbol - draws it from memory</li><li>February 6, 2000: Sees news coverage of more strange creatures, dismissed as &quot;wildlife&quot;</li><li>February 17, 2000: Doctor contacts manufacturer (Aurelian) about her non-response to Harmony</li><li>February 23, 2000: Receives call from &quot;Cognitive Baseline Research Group&quot; (Miter front)</li><li>February 25, 2000: Realizes she&#39;s heard &quot;Miter Corporation&quot; before but can&#39;t remember where</li><li>February 28, 2000: Goes to assessment appointment</li></ul><p><strong>Key Excerpts:</strong></p><p><em>On the conspiracy coffee shop guy (October 16, 1999):</em></p><blockquote><p>&quot;He started talking to me about this anxiety medicine everyone is on and how it&#39;s apparently connected to some crazy corporate occult conspiracy... OH and apparently there&#39;s this whole conspiracy theory about some research campus on the other side of the country. Saint... something? Saint Juniper maybe? He said it&#39;s supposed to be like an endurance research facility but he thinks they&#39;re doing &#39;classified government experiments on people.&#39;&quot;</p></blockquote><p><em>On seeing the creature (January 24, 2000):</em></p><blockquote><p>&quot;I was at the coffee shop this afternoon. Sitting by the window working on a layout. And I saw something outside. I don&#39;t even know how to describe it. It looked like an animal? But wrong. All wrong. The proportions were off. It moved in a way that didn&#39;t make sense. Like its joints bent in directions they shouldn&#39;t.&quot;</p></blockquote><p><em>On the geometric symbol dream (February 3, 2000):</em></p><blockquote><p>&quot;Just woke up from the most vivid dream I&#39;ve ever had in my life. Not even a dream. Something else. There was a symbol. A cross but not a normal cross. Geometric. Precise. The arms were different lengths. Circles at the ends of each arm. A perfect square in the center. It was spinning. Rotating in 3D... And I KNEW - the way you know things in dreams - that this shape was important. That it was DOING something.&quot;</p></blockquote><p><em>On being recruited (February 23, 2000):</em></p><blockquote><p>&quot;Woman called from something called &#39;Cognitive Baseline Research Group&#39; or something like that... Said my doctor had referred my case to them as part of a study on &#39;individual variation in response to medications&#39;... She gave me an address about 30 minutes away. I said I&#39;d think about it... They&#39;re listed as a subsidiary of something called &#39;Miter Corporation.&#39; I feel like I KNOW that name from somewhere.&quot;</p></blockquote><hr><h2 id="recovered-document" tabindex="-1">Recovered Document <a class="header-anchor" href="#recovered-document" aria-label="Permalink to &quot;Recovered Document&quot;">​</a></h2><p><strong>Note:</strong> This is a summary of the journal. Read the full journal at <a href="https://starryeyed77.dreamwidth.org/" target="_blank" rel="noreferrer">starryeyed77.dreamwidth.org</a></p><p><em>Key sections from the journal are provided in the Context &amp; Analysis above.</em></p><hr><h2 id="related-entries" tabindex="-1">Related Entries <a class="header-anchor" href="#related-entries" aria-label="Permalink to &quot;Related Entries&quot;">​</a></h2><ul><li><a href="./../entries/concepts/Harmony">Harmony</a></li><li><a href="./../entries/subjects/G-BOY">G*BOY / G-304</a></li><li><a href="./../entries/organizations/Miter-Corporation">Miter Corporation</a></li><li><a href="./../entries/organizations/Aurelian-Systems">Aurelian Systems</a></li><li><a href="./../entries/locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a></li><li><a href="./JOURNAL_ENTRIES_NIGHTBLOOM_99">Journal Entries - nightbloom_99</a></li></ul><h2 id="community-notes" tabindex="-1">Community Notes <a class="header-anchor" href="#community-notes" aria-label="Permalink to &quot;Community Notes&quot;">​</a></h2><p><em>(To be added)</em></p>',25)])])}const p=t(i,[["render",n]]);export{h as __pageData,p as default};
